class Solution {
public:
    long long minEnd(int n, int x) {
        long long val = n - 1;
        long long ans = x;
        int bit_pos = 0, val_pos = 0;
        while ((1LL << val_pos) <= val) {
            while ((ans >> bit_pos) & 1LL) {
                bit_pos++;
            }
            if ((val >> val_pos) & 1LL) {
                ans |= (1LL << bit_pos);
            }
            bit_pos++;
            val_pos++;
        }
        return ans;
    }
};

